{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Brie fl y, studies were eligible if they were (i) reporting PCR laboratory diagnosis of COVID-19 as an independent variable (ii) reporting one or more COVID-19 risk factors among HCWs with risk estimates (relative risk, odds ratio or hazard ratio) (iii) original, quantitative study design published in English or Mandarian.",
      "reason": "The manuscript specifies the study design (original, quantitative), the population (HCWs), and the outcome/exposure criteria (PCR diagnosis, risk factors with estimates)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "published in English or Mandarian.",
      "reason": "The manuscript specifies the language restriction but fails to specify criteria regarding dissemination year or publication status (e.g., peer-reviewed vs. grey literature)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Reasons for exclusion at full text review stage included lack of PCR con fi rmation of COVID-19 infection [24, 31 e 33, 36], and lack of evidence on risk estimates for COVID-19 risk factors [28].",
      "reason": "The authors distinguish between studies excluded due to the outcome not being measured (lack of PCR confirmation) and studies excluded because results were not reported (lack of risk estimates)."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "The summary measures calculated include a narrative report of all reported risk factors in the included studies, a pooled incidence of COVID-19 among health workers from included cohort studies and a pooled relative risk for risk factors reported by at least 2 included studies.",
      "reason": "The manuscript specifies the groups used for synthesis (pooled incidence for cohort studies, pooled relative risk for specific risk factors) and links these to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript imposes restrictions on study eligibility (e.g., language: English or Mandarin; study design: original, quantitative) but does not provide a rationale for these restrictions."
    }
  ],
  "confidence": 100
}

